import { useEffect } from 'react'
import { overviewService } from '../../services/clinical'
import type { Waveform } from '../../types'

/**
 * Buffers synthetic waveform chunks generated by the API. Chunks are aligned to
 * wall-clock time (CHUNK seconds each) so the canvas can look up the sample for
 * "now" and consecutive chunks join seamlessly.
 */
export const CHUNK = 6
type Channel = 'ecg' | 'pleth' | 'resp'

const chunks = new Map<string, Waveform>() // `${monitorId}:${index}`
const inflight = new Set<string>()

export function sampleAt(monitorId: string, channel: Channel, t: number): number | null {
  const k = Math.floor(t / CHUNK)
  const w = chunks.get(`${monitorId}:${k}`)
  const data = w?.[channel]
  if (!w || !data || data.length === 0) return null
  const i = Math.floor((t - w.start) * w.fs)
  return i >= 0 && i < data.length ? data[i] : null
}

export function isOnline(monitorId: string, t: number): boolean | null {
  const w = chunks.get(`${monitorId}:${Math.floor(t / CHUNK)}`)
  return w ? w.online : null
}

function prune(current: number) {
  for (const key of chunks.keys()) {
    const k = Number(key.split(':')[1])
    if (k < current - 1) chunks.delete(key)
  }
}

async function loadAll(k: number) {
  const key = `all:${k}`
  if (inflight.has(key)) return
  inflight.add(key)
  try {
    const data = await overviewService.waveforms(k * CHUNK, CHUNK)
    for (const [id, w] of Object.entries(data)) chunks.set(`${id}:${k}`, w)
  } catch {
    /* gaps are drawn as flat lines; the next poll retries */
  } finally {
    inflight.delete(key)
  }
}

async function loadOne(monitorId: string, k: number) {
  const key = `${monitorId}:${k}`
  if (inflight.has(key) || chunks.get(key)?.resp) return
  inflight.add(key)
  try {
    chunks.set(key, await overviewService.waveform(monitorId, k * CHUNK, CHUNK))
  } catch {
    /* retry on next poll */
  } finally {
    inflight.delete(key)
  }
}

/** Keeps the current and next chunk loaded. `monitorId` = single monitor with respiration; omitted = all monitors. */
export function useWaveformFeed(enabled: boolean, monitorId?: string, refreshKey?: unknown) {
  useEffect(() => {
    if (!enabled) return
    let cancelled = false
    const poll = () => {
      if (cancelled) return
      const now = Date.now() / 1000
      const k = Math.floor(now / CHUNK)
      prune(k)
      const want = [k]
      if (now - k * CHUNK > CHUNK / 2) want.push(k + 1)
      for (const idx of want) {
        const have = monitorId ? chunks.has(`${monitorId}:${idx}`) && chunks.get(`${monitorId}:${idx}`)?.resp : [...chunks.keys()].some((c) => c.endsWith(`:${idx}`))
        if (!have) void (monitorId ? loadOne(monitorId, idx) : loadAll(idx))
      }
    }
    poll()
    const id = window.setInterval(poll, 1000)
    return () => {
      cancelled = true
      window.clearInterval(id)
    }
  }, [enabled, monitorId])

  // Vital signs changed (new simulation tick): regenerate upcoming chunks with the new rate.
  useEffect(() => {
    if (!enabled || refreshKey === undefined) return
    const k = Math.floor(Date.now() / 1000 / CHUNK)
    for (const key of [...chunks.keys()]) {
      if (Number(key.split(':')[1]) > k && (!monitorId || key.startsWith(monitorId))) chunks.delete(key)
    }
  }, [enabled, monitorId, refreshKey])
}
